+  b.v.y += (buoy - gam * b.v.y) * dt;
+  b.p.addScaledVector(b.v, dt);
+
+  const rho = Math.hypot(b.p.x, b.p.z);
+  const rMax = Math.max(0.002, rInnerAt(b.p.y) - r * 1.05);
+  if (rho > rMax) {
+    const k = rMax / rho;
+    b.p.x *= k; b.p.z *= k;
+    const vr = (b.v.x * b.p.x + b.v.z * b.p.z) / (rMax * rMax);
+    if (vr > 0) { b.v.x -= vr * b.p.x; b.v.z -= vr * b.p.z; }
+  }
+  const yMax = VES.yt - 0.012 - r * 1.2;
+  if (b.p.y > yMax) { b.p.y = yMax; if (b.v.y > 0) b.v.y *= -0.3; }
+
+  const sT = 1 + clamp(b.v.y * 16, -0.3, 0.75);
+  b.s += (sT - b.s) * (1 - Math.exp(-4 * dt));
+  if (b.cool > 0) b.cool -= dt;
+
+  if (b.v.y < 0 && b.p.y - 0.9 * r < poolTop()) { b.state = 'absorb'; b.target = null; b.tau = 0.5; return; }
+
+  if (!b.hasChild && W.blobs.length < MAXB - 1) {
+    if (r > RMAX) spawnChild(b, 0.4);
+    else if (b.s > 1.42 && b.v.y > 0.012 && rnd() < 0.6 * dt) spawnChild(b, 0.12);
+  }
+}
+
+function spawnChild(par, frac) {
+  const c = newBlob('birth', 0, par.p.x, par.p.y - rOf(par.V) * 0.9, par.p.z, par.T);
+  c.Vt = par.V * frac;
+  c.parent = par;
+  c.cool = 3.0;
+  par.hasChild = true;
+  W.blobs.push(c);
+}
+
+function updateBirth(b, dt) {
+  const par = b.parent;
+  if (!par || par.removed || par.V < 1e-7) {
+    b.state = 'free'; b.parent = null;
+    if (par) par.hasChild = false;
+    return;
+  }
+  const dV = Math.min(b.Vt * 0.8 * dt, Math.max(b.Vt - b.V, 0), par.V * 0.5);
+  par.V -= dV; b.V += dV; b.T = par.T;
+  const goal = _v.set(par.p.x, par.p.y - (rOf(par.V) + rOf(b.V)) * 0.8, par.p.z);
+  b.p.lerp(goal, 1 - Math.exp(-6 * dt));
+  if (b.V >= b.Vt * 0.97) {
+    b.state = 'free'; b.parent = null;
+    b.v.copy(par.v).multiplyScalar(0.4);
+    par.hasChild = false;
+  }
+}
+
+function updateAbsorb(b, dt) {
+  let tgt = b.target;
+  let guard = 0;
+  while (tgt && tgt.state === 'absorb' && guard++ < 16) tgt = tgt.target;
+  const dV = Math.min(b.V, b.V * dt / b.tau);
+  b.V -= dV;
+  let goal;
+  if (tgt) {
+    const nv = tgt.V + dV;
+    if (nv > 0) tgt.v.lerp(b.v, dV / nv);
+    tgt.V = nv;
+    goal = tgt.p;
+  } else {
+    W.pool.V += dV;
+    goal = _v.set(b.p.x, poolTop() - 0.4 * rOf(b.V), b.p.z);
+  }
+  b.p.lerp(goal, 1 - Math.exp(-3 * dt));
+  if (b.V < 3e-9) b.removed = true;
+}
+
+function stepSim(dt) {
+  W.t += dt;
+  W.lamp += ((W.power ? 1 : 0) - W.lamp) * (1 - Math.exp(-(W.power ? 0.3 : 0.2) * dt));
+  W.hot = AMB + (1 - AMB) * W.lamp * (0.62 + 0.38 * W.heat);
+  W.pool.T += (W.hot - W.pool.T) * (1 - Math.exp(-0.5 * dt));
+
+  // wax amount: scale every volume gently toward the goal
+  let total = W.pool.V;
+  for (const b of W.blobs) total += b.V;
+  const goal = W.waxFrac * VINT;
+  if (total > 1e-12) {
+    const f = 1 + (goal / total - 1) * (1 - Math.exp(-0.8 * dt));
+    W.pool.V *= f;
+    for (const b of W.blobs) b.V *= f;
+  }
+
+  // a new bud swells on the warm pool
+  W.spawnCd -= dt;
+  if (W.spawnCd <= 0 && W.lamp > 0.35 && W.pool.T > 0.45 && W.pool.V > 2.5e-5 &&
+      W.blobs.length < MAXB - 2 && !W.blobs.some((b) => b.state === 'bud')) {
+    const pt = poolTop();
+    const [x, z] = spot(rInnerAt(pt) * 0.55);
+    const b = newBlob('bud', sphereV(0.0035), x, pt + 0.001, z, W.pool.T);
+    b.Rt = 0.015 + rnd() * 0.008;
+    W.pool.V -= b.V;
+    W.blobs.push(b);
+    W.spawnCd = 0.4 + rnd() * 1.2;
+  }
+
+  for (const b of W.blobs.slice()) {
+    if (b.state === 'bud') updateBud(b, dt);
+    else if (b.state === 'free') updateFree(b, dt);
+    else if (b.state === 'birth') updateBirth(b, dt);
+    else if (b.state === 'absorb') updateAbsorb(b, dt);
+  }
+
+  // free blobs that overlap fuse: smaller one drains into the larger
+  const fr = W.blobs.filter((b) => b.state === 'free');
+  for (let i = 0; i < fr.length; i++) for (let j = i + 1; j < fr.length; j++) {
+    const a = fr[i], c = fr[j];
+    if (a.state !== 'free' || c.state !== 'free' || a.cool > 0 || c.cool > 0) continue;
+    if (a.p.distanceTo(c.p) < 0.9 * (rOf(a.V) + rOf(c.V))) {
+      const small = a.V < c.V ? a : c;
+      const big = small === a ? c : a;
+      small.state = 'absorb'; small.target = big; small.tau = 0.35;
+    }
+  }
+
+  // free blobs that sink into the pool drain into it
+  const pt = poolTop();
+  for (const b of W.blobs) {
+    if (b.state === 'free' && b.v.y < 0 && b.p.y - 0.9 * rOf(b.V) < pt) {
+      b.state = 'absorb'; b.target = null; b.tau = 0.5;
+    }
+  }
+
+  const dead = W.blobs.filter((b) => b.removed || (b.state === 'absorb' && b.V < 3e-9));
+  if (dead.length) {
+    for (const d of dead) {
+      let t = d.target;
+      while (t && dead.includes(t)) t = t.target;
+      for (const o of W.blobs) {
+        if (o.target === d) o.target = t;
+        if (o.parent === d) o.parent = null;
+      }
+    }
+    W.blobs = W.blobs.filter((b) => !dead.includes(b));
+  }
+}
+
+function ellipsoid(b) {
+  const r = Math.max(rOf(b.V), 0.0012) * (1 + 0.12 * (b.T - TN));
+  const s = Math.max(0.55, b.s);
+  const rh = r / Math.cbrt(s), ry = r * Math.pow(s, 2 / 3);
+  const sp = Math.min(1, b.v.length() / 0.04);
+  const a = 0.025 + 0.07 * sp;
+  const w1 = Math.sin(W.t * b.f1 + b.ph), w2 = Math.cos(W.t * b.f2 + b.ph * 1.3);
+  _e.set(rh * (1 + a * w1), ry * (1 - 0.6 * a * w2), rh * (1 + a * w2));
+  return _e;
+}
+
+// initial state, pre-run so the lamp is already busy on first paint
+W.hot = AMB + (1 - AMB) * (0.62 + 0.38 * W.heat);
+W.pool.V = W.waxFrac * VINT * 0.4;
+W.pool.T = 0.9;
+for (let i = 0; i < 5; i++) {
+  const y = VES.yb + 0.04 + rnd() * 0.2;
+  const [x, z] = spot(rInnerAt(y) * 0.6);
+  const b = newBlob('free', W.waxFrac * VINT * 0.12 * (0.8 + 0.4 * rnd()), x, y, z, 0.5);
+  b.T = AMB + (W.hot - AMB) * Math.exp(-(y - VES.yb) / 0.16);
+  W.blobs.push(b);
+}
+for (let i = 0; i < 60 * 120; i++) stepSim(SIM_DT);
+
+/* =====================================================================
+   Presets and per-frame uniform sync
+   ===================================================================== */
+const PRESETS = [
+  { name: 'Classic red in yellow', wax: [0.92, 0.10, 0.03], liq: [0.98, 0.74, 0.14], sw: ['#d8170d', '#ffc42a'] },
+  { name: 'Cobalt in ruby', wax: [0.10, 0.24, 0.95], liq: [0.92, 0.16, 0.20], sw: ['#2456f0', '#c81e3a'] },
+  { name: 'Lime in navy', wax: [0.50, 0.95, 0.18], liq: [0.10, 0.24, 0.80], sw: ['#9ee61e', '#15286e'] },
+  { name: 'Magenta in teal', wax: [0.95, 0.12, 0.55], liq: [0.10, 0.78, 0.72], sw: ['#f0208c', '#1ec7b8'] },
+  { name: 'Amber in violet', wax: [1.00, 0.52, 0.08], liq: [0.42, 0.12, 0.82], sw: ['#ffad1f', '#5a1fb0'] }
+];
+const sigOf = (T, d) => new THREE.Vector3(
+  -Math.log(clamp(T[0], 0.01, 1)) / d, -Math.log(clamp(T[1], 0.01, 1)) / d, -Math.log(clamp(T[2], 0.01, 1)) / d);
+const cur = {
+  wS: sigOf(PRESETS[0].wax, 0.02), lS: sigOf(PRESETS[0].liq, 0.05),
+  wC: new THREE.Color().setRGB(...PRESETS[0].wax), lC: new THREE.Color().setRGB(...PRESETS[0].liq)
+};
+const tgtW = PRESETS[0], tgt = { wS: cur.wS.clone(), lS: cur.lS.clone(), wC: cur.wC.clone(), lC: cur.lC.clone() };
+
+function updateVisuals(dt) {
+  let occ = 0, cx = 0, cy = 0, cz = 0, cw = 0;
+  for (const b of W.blobs) {
+    const r = rOf(b.V) + 1e-4;
+    const dy = b.p.y - VES.yb;
+    const d2 = b.p.x * b.p.x + b.p.z * b.p.z;
+    if (dy > -0.01 && dy < 0.14) occ += Math.exp(-d2 / (r * r * 0.8)) * (1 - Math.max(dy, 0) / 0.14) * 0.9;
+    cx += b.p.x * b.V; cy += b.p.y * b.V; cz += b.p.z * b.V; cw += b.V;
+  }
+  const pt = poolTop();
+  occ += 0.12 * clamp((pt - VES.yb) / 0.03, 0, 1);
+  cy += (VES.yb + (pt - VES.yb) * 0.5) * W.pool.V;
+  cw += W.pool.V;
+  W.occS += (clamp(occ, 0, 1) - W.occS) * (1 - Math.exp(-3 * dt));
+
+  const cxn = cw > 0 ? cx / cw : 0, cyn = cw > 0 ? cy / cw : 0.2, czn = cw > 0 ? cz / cw : 0;
+  const k = 1 - Math.exp(-2 * dt);
+  const tx = LAMP.x + cxn * 0.25, ty = LAMP.y + (cyn - 0.2) * 0.1, tz = LAMP.z + czn * 0.25;
+  W.lampPos.x += (tx - W.lampPos.x) * k;
+  W.lampPos.y += (ty - W.lampPos.y) * k;
+  W.lampPos.z += (tz - W.lampPos.z) * k;
+  lampLight.position.copy(W.lampPos);
+
+  const flick = 1 + 0.02 * Math.sin(W.t * 7.3) + 0.012 * Math.sin(W.t * 17.1 + 1.3) + 0.008 * Math.sin(W.t * 2.1);
+  W.light = Math.pow(W.lamp, 1.3) * (1 - 0.3 * W.occS) * flick;
+  lampLight.intensity = LAMP_I * W.light;
+  scene.environmentIntensity = (0.05 + 0.35 * W.room) * (0.4 + 0.6 * W.lamp);
+  wallGlow.material.opacity = 0.2 * W.light;
+  spill.material.opacity = 0.14 * W.light;
+  ringGlow.material.color.setRGB(1.0 * W.light, 0.6 * W.light, 0.25 * W.light).multiplyScalar(5);
+  lever.rotation.z += ((W.power ? 0.4 : -0.4) - lever.rotation.z) * (1 - Math.exp(-10 * dt));
+
+  const kc = 1 - Math.exp(-5 * dt);
+  cur.wS.lerp(tgt.wS, kc);
+  cur.lS.lerp(tgt.lS, kc);
+  cur.wC.lerp(tgt.wC, kc);
+  cur.lC.lerp(tgt.lC, kc);
+}
+
+function syncUniforms() {
+  U.uPoolTop.value = poolTop();
+  U.uPoolT.value = W.pool.T;
+  U.uTime.value = W.t;
+  U.uBulbI.value = BULB_I * W.light;
+  U.uWaxSig.value.copy(cur.wS);
+  U.uLiqSig.value.copy(cur.lS);
+  U.uWaxCol.value.copy(cur.wC);
+  U.uLiqCol.value.copy(cur.lC);
+  const n = Math.min(W.blobs.length, MAXB);
+  for (let i = 0; i < MAXB; i++) {
+    const A = U.uBlobA.value[i], B = U.uBlobB.value[i];
+    if (i < n) {
+      const b = W.blobs[i], e = ellipsoid(b);
+      A.set(b.p.x, b.p.y, b.p.z, clamp(b.T, 0, 1));
+      B.set(e.x, e.y, e.z, 1);
+    } else {
+      B.w = 0;
+    }
+  }
+}
+
+/* =====================================================================
+   Frame loop
+   ===================================================================== */
+function renderFrame(dt) {
+  U.uViewProj.value.multiplyMatrices(camera.projectionMatrix, camera.matrixWorldInverse);
+  U.uCamPos.value.copy(camera.position);
+  renderer.setRenderTarget(atlasRT);
+  renderer.render(fieldScene, orthoCam);
+  renderer.setRenderTarget(rtMain);
+  renderer.render(scene, camera);
+  copyU.tSrc.value = rtMain.texture;
+  copyMat.uniforms.tSrc.value = rtMain.texture;
+  renderer.setRenderTarget(rtBg);
+  renderer.render(copyScene, orthoCam);
+  renderer.setRenderTarget(rtMain);
+  renderer.autoClear = false;
+  renderer.render(vesselScene, camera);
+  renderer.autoClear = true;
+  renderer.setRenderTarget(null);
+  copyPass.uniforms.tSrc.value = rtMain.texture;
+  grade.uniforms.uTime.value = performance.now() / 1000;
+  composer.render(dt);
+}
+
+let prevT = performance.now(), acc = 0, emaMs = 16, lastQ = 0;
+function adaptQuality(now) {
+  if (now - lastQ < 1500) return;
+  if (emaMs > 24 && quality > 0.5) { quality = Math.round((quality - 0.1) * 10) / 10; applyQuality(); lastQ = now; }
+  else if (emaMs < 14 && quality < 1) { quality = Math.round((quality + 0.1) * 10) / 10; applyQuality(); lastQ = now; }
+}
+function frame(now) {
+  requestAnimationFrame(frame);
+  const dtReal = clamp((now - prevT) / 1000, 0, 0.05);
+  prevT = now;
+  emaMs = emaMs * 0.92 + dtReal * 1000 * 0.08;
+  adaptQuality(now);
+  acc += dtReal * W.flow;
+  let steps = 0;
+  while (acc >= SIM_DT && steps < 24) { stepSim(SIM_DT); acc -= SIM_DT; steps++; }
+  if (steps === 24) acc = 0;
+  controls.update();
+  updateVisuals(dtReal);
+  syncUniforms();
+  renderFrame(dtReal);
+}
+
+/* =====================================================================
+   Controls
+   ===================================================================== */
+const $ = (id) => document.getElementById(id);
+const powerBtn = $('power');
+function setPower(on) {
+  W.power = on;
+  powerBtn.setAttribute('aria-pressed', on ? 'true' : 'false');
+}
+powerBtn.addEventListener('click', () => setPower(!W.power));
+
+const chipsEl = $('chips');
+function setPreset(i) {
+  W.preset = i;
+  const p = PRESETS[i];
+  tgt.wS.copy(sigOf(p.wax, 0.02));
+  tgt.lS.copy(sigOf(p.liq, 0.05));
+  tgt.wC.setRGB(...p.wax);
+  tgt.lC.setRGB(...p.liq);
+  [...chipsEl.children].forEach((el, j) => el.setAttribute('aria-pressed', j === i ? 'true' : 'false'));
+  $('pname').textContent = p.name;
+}
+PRESETS.forEach((p, i) => {
+  const b = document.createElement('button');
+  b.className = 'chip';
+  b.title = p.name;
+  b.setAttribute('aria-label', p.name);
+  b.style.setProperty('--a', p.sw[0]);
+  b.style.setProperty('--b', p.sw[1]);
+  b.addEventListener('click', () => setPreset(i));
+  chipsEl.appendChild(b);
+});
+setPreset(0);
+
+function bindRange(id, outId, fmt, apply) {
+  const el = $(id), out = $(outId);
+  const upd = () => {
+    const v = parseFloat(el.value);
+    apply(v);
+    out.textContent = fmt(v);
+    const pct = ((v - el.min) / (el.max - el.min)) * 100;
+    el.style.setProperty('--p', pct + '%');
+  };
+  el.addEventListener('input', upd);
+  el.value = el.getAttribute('value') ?? el.value;
+  upd();
+}
+$('heat').value = W.heat;
+$('flow').value = W.flow;
+$('wax').value = W.waxFrac;
+$('room').value = W.room;
+bindRange('heat', 'heatO', (v) => Math.round(v * 100) + '%', (v) => { W.heat = v; });
+bindRange('flow', 'flowO', (v) => v.toFixed(2) + '×', (v) => { W.flow = v; });
+bindRange('wax', 'waxO', (v) => Math.round(v * 100) + '%', (v) => { W.waxFrac = v; });
+bindRange('room', 'roomO', (v) => Math.round(v * 100) + '%', (v) => { W.room = v; });
+
+$('orbit').addEventListener('change', (e) => { controls.autoRotate = e.target.checked; controls.autoRotateSpeed = 0.8; });
+
+// click the inline cord switch to toggle power
+const ray = new THREE.Raycaster();
+const ndc = new THREE.Vector2();
+canvas.addEventListener('pointerdown', (e) => {
+  const r = canvas.getBoundingClientRect();
+  ndc.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
+  ray.setFromCamera(ndc, camera);
+  if (ray.intersectObject(switchMesh, false).length) setPower(!W.power);
+});
+
+onResize();
+requestAnimationFrame(frame);
+</script>
+</body>
+</html>

