   ===================================================================== */
const PRESETS = [
  { name: 'Classic red in yellow', wax: [0.92, 0.10, 0.03], liq: [0.98, 0.74, 0.14], sw: ['#d8170d', '#ffc42a'] },
  { name: 'Cobalt in ruby', wax: [0.10, 0.24, 0.95], liq: [0.92, 0.16, 0.20], sw: ['#2456f0', '#c81e3a'] },
  { name: 'Lime in navy', wax: [0.50, 0.95, 0.18], liq: [0.10, 0.24, 0.80], sw: ['#9ee61e', '#15286e'] },
  { name: 'Magenta in teal', wax: [0.95, 0.12, 0.55], liq: [0.10, 0.78, 0.72], sw: ['#f0208c', '#1ec7b8'] },
  { name: 'Amber in violet', wax: [1.00, 0.52, 0.08], liq: [0.42, 0.12, 0.82], sw: ['#ffad1f', '#5a1fb0'] }
];
const sigOf = (T, d) => new THREE.Vector3(
  -Math.log(clamp(T[0], 0.01, 1)) / d, -Math.log(clamp(T[1], 0.01, 1)) / d, -Math.log(clamp(T[2], 0.01, 1)) / d);
const cur = {
  wS: sigOf(PRESETS[0].wax, 0.02), lS: sigOf(PRESETS[0].liq, 0.05),
  wC: new THREE.Color().setRGB(...PRESETS[0].wax), lC: new THREE.Color().setRGB(...PRESETS[0].liq)
};
const tgt = { wS: cur.wS.clone(), lS: cur.lS.clone(), wC: cur.wC.clone(), lC: cur.lC.clone() };

function updateVisuals(dt) {
  let occ = 0, cx = 0, cy = 0, cz = 0, cw = 0;
  for (const b of W.blobs) {
    const r = rOf(b.V) + 1e-4;
    const dy = b.p.y - VES.yb;
    const d2 = b.p.x * b.p.x + b.p.z * b.p.z;
    if (dy > -0.01 && dy < 0.14) occ += Math.exp(-d2 / (r * r * 0.8)) * (1 - Math.max(dy, 0) / 0.14) * 0.9;
    cx += b.p.x * b.V; cy += b.p.y * b.V; cz += b.p.z * b.V; cw += b.V;
  }
  const pt = poolTop();
  occ += 0.12 * clamp((pt - VES.yb) / 0.03, 0, 1);
  cy += (VES.yb + (pt - VES.yb) * 0.5) * W.pool.V;
  cw += W.pool.V;
  W.occS += (clamp(occ, 0, 1) - W.occS) * (1 - Math.exp(-3 * dt));

  const cxn = cw > 0 ? cx / cw : 0, cyn = cw > 0 ? cy / cw : 0.2, czn = cw > 0 ? cz / cw : 0;
  const k = 1 - Math.exp(-2 * dt);
  const tx = LAMP.x + cxn * 0.25, ty = LAMP.y + (cyn - 0.2) * 0.1, tz = LAMP.z + czn * 0.25;
  W.lampPos.x += (tx - W.lampPos.x) * k;
  W.lampPos.y += (ty - W.lampPos.y) * k;
  W.lampPos.z += (tz - W.lampPos.z) * k;
  lampLight.position.copy(W.lampPos);

  const flick = 1 + 0.02 * Math.sin(W.t * 7.3) + 0.012 * Math.sin(W.t * 17.1 + 1.3) + 0.008 * Math.sin(W.t * 2.1);
  W.light = Math.pow(W.lamp, 1.3) * (1 - 0.3 * W.occS) * flick;
  lampLight.intensity = LAMP_I * W.light;
  scene.environmentIntensity = (0.05 + 0.35 * W.room) * (0.4 + 0.6 * W.lamp);
  wallGlow.material.opacity = 0.2 * W.light;
  spill.material.opacity = 0.14 * W.light;
  ringGlow.material.color.setRGB(1.0 * W.light, 0.6 * W.light, 0.25 * W.light).multiplyScalar(5);
  lever.rotation.z += ((W.power ? 0.4 : -0.4) - lever.rotation.z) * (1 - Math.exp(-10 * dt));

  const kc = 1 - Math.exp(-5 * dt);
  cur.wS.lerp(tgt.wS, kc);
  cur.lS.lerp(tgt.lS, kc);
  cur.wC.lerp(tgt.wC, kc);
  cur.lC.lerp(tgt.lC, kc);
}

function syncUniforms() {
  U.uPoolTop.value = poolTop();
  U.uPoolT.value = W.pool.T;
  U.uTime.value = W.t;
  U.uBulbI.value = BULB_I * W.light;

